import React from "react";
import ReactDOM from "react-dom/client";
import { BrowserRouter, Routes, Route } from "react-router-dom";
import "./index.css";

import HomePage from "./landing_page/home/HomePage";
import NotFound from "./landing_page/NotFound";
import Navbar from "./landing_page/Navbar";
import Footer from "./landing_page/Footer";
import AuthSignup from "./auth/Signup";
import AuthLogin from "./auth/Login";

// runtime sanity check: ensure none of the imported components are undefined
const IMPORTS = { HomePage, NotFound, Navbar, Footer, AuthSignup, AuthLogin };
const missing = Object.entries(IMPORTS).filter(([, v]) => v == null);
if (missing.length > 0) {
  console.error(
    "Missing React component imports:",
    missing.map(([k]) => k),
  );
  const root = ReactDOM.createRoot(document.getElementById("root"));
  root.render(
    React.createElement(
      "div",
      { style: { padding: 24, fontFamily: "sans-serif", color: "#c00" } },
      React.createElement("h2", null, "Import error"),
      React.createElement(
        "p",
        null,
        "The following components failed to import:",
      ),
      React.createElement(
        "ul",
        null,
        missing.map(([k]) => React.createElement("li", { key: k }, k)),
      ),
    ),
  );
  throw new Error("One or more component imports are undefined");
}

const root = ReactDOM.createRoot(document.getElementById("root"));
// Helper that returns a safe React element or a visible error message
const safeElement = (Comp) => {
  if (typeof Comp === "function" || typeof Comp === "string") {
    return <Comp />;
  }
  return (
    <div style={{ padding: 24, color: "#900" }}>
      <h2>Import/render error</h2>
      <p>
        One of the route components failed to import or is not a valid React
        component.
      </p>
    </div>
  );
};

root.render(
  <BrowserRouter>
    <Navbar />
    <Routes>
      <Route path="/" element={safeElement(HomePage)} />
      <Route path="/auth/signup" element={safeElement(AuthSignup)} />
      <Route path="/auth/login" element={safeElement(AuthLogin)} />
      <Route path="*" element={safeElement(NotFound)} />
    </Routes>
    <Footer />
  </BrowserRouter>,
);
